import React, { useState, useMemo } from 'react';
import { motion } from 'motion/react';
import WhiteButton from '../utils/WhiteButton';
import { useCart } from '../context/CartContext';

const ProductCard = ({ image, title, description, price, id, availability, applyPromotions, variantsConfig }) => {
  const { addItem } = useCart();

  // State for selected variants: { "Tamaño": "G", ... }
  const [selectedVariants, setSelectedVariants] = useState({});

  // Calculate total price including variants
  const totalPrice = useMemo(() => {
    let total = parseFloat(price) || 0;

    if (variantsConfig && selectedVariants) {
      Object.entries(selectedVariants).forEach(([variantType, variantOption]) => {
        const variantPrice = variantsConfig[variantType]?.[variantOption];
        if (variantPrice) {
          total += parseFloat(variantPrice);
        }
      });
    }

    return total;
  }, [price, variantsConfig, selectedVariants]);

  // Handle variant selection
  const handleVariantChange = (variantType, option) => {
    setSelectedVariants(prev => ({
      ...prev,
      [variantType]: option
    }));
  };

  const handleAddClick = () => {
    addItem({
      id,
      image,
      title,
      description,
      price: totalPrice, // Use calculated price
      basePrice: price, // Keep original price for reference
      availability,
      applyPromotions,
      selectedVariants: Object.keys(selectedVariants).length > 0 ? selectedVariants : null,
      variantsConfig
    });
  };

  // Determine availability status - simplified for cleaner design
  const isAvailable = availability > 0;

  return (
    <motion.div
      className="group relative w-full h-full"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
      whileHover={{ y: -2 }}
    >
      {/* Image Container - Top section with fixed aspect ratio */}
      <div className="relative aspect-square bg-white/5 backdrop-blur-md rounded-3xl overflow-hidden mb-4 border border-white/10 group-hover:border-white/20 transition-all duration-500">

        {/* Status Indicators - Over the image */}
        <div className="absolute top-3 left-3 right-3 flex justify-between items-start z-20 pointer-events-none">
          {/* Promotion Badge */}
          {applyPromotions === 1 && (
            <motion.div
              className="bg-gradient-to-r from-purple-500/90 to-indigo-500/90 backdrop-blur-sm px-2.5 py-1 rounded-full"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 0.2 }}
            >
              <span className="text-xs font-medium text-white">Promo</span>
            </motion.div>
          )}

          {/* Availability Indicator */}
          <motion.div
            className={`px-2.5 py-1 rounded-full backdrop-blur-sm transition-all duration-300 ${isAvailable
              ? 'bg-black/80 border border-gray-700/50'
              : 'bg-red-500/90 border border-red-400/50'
              }`}
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.3 }}
          >
            <span className={`text-xs font-medium ${isAvailable ? 'text-white' : 'text-white'
              }`}>
              {isAvailable ? availability : 'Agotado'}
            </span>
          </motion.div>
        </div>

        {/* Image with click functionality - removed click interaction */}
        <motion.div
          className="relative w-full h-full"
          whileHover={{ scale: 1.02 }}
          transition={{ duration: 0.2 }}
        >
          {/* Background gradient */}
          <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/20"></div>

          {/* Main image or fallback */}
          {image ? (
            <img
              src={image}
              alt={title}
              className="w-full h-full object-cover transition-all duration-700 group-hover:scale-105"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-gray-600/20 to-gray-800/20 flex items-center justify-center">
              <svg className="w-16 h-16 text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
          )}
        </motion.div>
      </div>

      {/* Content Section - Below image, clean layout */}
      <div className="px-2">
        {/* Title */}
        <h3 className="text-white font-semibold text-base sm:text-lg leading-tight mb-2 line-clamp-2 group-hover:text-white/90 transition-colors duration-300">
          {title || 'Producto sin título'}
        </h3>

        {/* Description - Always visible */}
        {description && (
          <p className="text-white/80 text-xs sm:text-sm leading-relaxed mb-3 line-clamp-3">
            {description}
          </p>
        )}

        {/* Variants Selection */}
        {variantsConfig && Object.keys(variantsConfig).length > 0 && (
          <div className="mb-3 space-y-2">
            {Object.entries(variantsConfig).map(([variantType, options]) => (
              <div key={variantType} className="space-y-1">
                <label className="text-white/70 text-xs font-medium">{variantType}</label>
                <select
                  value={selectedVariants[variantType] || ''}
                  onChange={(e) => handleVariantChange(variantType, e.target.value)}
                  className="w-full p-2 text-xs rounded-lg bg-white/10 backdrop-blur-sm text-white border border-white/20 focus:border-white/40 focus:outline-none focus:ring-2 focus:ring-white/20 transition-all duration-200"
                >
                  <option value="" className="bg-gray-900">Seleccionar {variantType}</option>
                  {Object.entries(options).map(([optionName, optionPrice]) => (
                    <option key={optionName} value={optionName} className="bg-gray-900">
                      {optionName} (+${optionPrice})
                    </option>
                  ))}
                </select>
              </div>
            ))}
          </div>
        )}

        {/* Price and Add Button */}
        <div className="flex items-center justify-between">
          <div className="text-2xl sm:text-3xl font-bold text-white">
            ${totalPrice.toFixed(2)}
          </div>

          <motion.div
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            <button
              onClick={isAvailable ? handleAddClick : undefined}
              disabled={!isAvailable}
              className={`w-10 h-10 sm:w-12 sm:h-12 rounded-full flex items-center justify-center transition-all duration-300 ${isAvailable
                ? 'bg-white text-gray-900 hover:bg-white/90 shadow-lg hover:shadow-white/25'
                : 'bg-gray-600/50 text-gray-400 cursor-not-allowed'
                }`}
              aria-label={`Agregar ${title} al carrito`}
            >
              <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
              </svg>
            </button>
          </motion.div>
        </div>
      </div>
    </motion.div>
  );
};

export default ProductCard;
