import React, { createContext, useContext, useReducer } from 'react';
import { toast } from 'sonner';

const CartContext = createContext();

// Helper function to generate unique cart item ID based on product ID and variants
const generateCartItemId = (productId, selectedVariants) => {
  if (!selectedVariants || Object.keys(selectedVariants).length === 0) {
    return `${productId}`;
  }
  const variantString = JSON.stringify(selectedVariants);
  return `${productId}_${variantString}`;
};

// Helper function to check if two items are the same (same product and same variants)
const isSameItem = (item1, item2) => {
  if (item1.id !== item2.id) return false;

  const variants1 = item1.selectedVariants || {};
  const variants2 = item2.selectedVariants || {};

  return JSON.stringify(variants1) === JSON.stringify(variants2);
};

const cartReducer = (state, action) => {
  switch (action.type) {
    case 'ADD_ITEM':
      const existingItem = state.items.find(item => isSameItem(item, action.payload));
      if (existingItem) {
        return {
          ...state,
          items: state.items.map(item =>
            isSameItem(item, action.payload)
              ? { ...item, quantity: item.quantity + 1 }
              : item
          )
        };
      }
      // Generate unique cart ID for new item
      const cartItemId = generateCartItemId(action.payload.id, action.payload.selectedVariants);
      return {
        ...state,
        items: [...state.items, { ...action.payload, cartItemId, quantity: 1 }]
      };

    case 'REMOVE_ITEM':
      return {
        ...state,
        items: state.items.filter(item => item.cartItemId !== action.payload)
      };

    case 'UPDATE_QUANTITY':
      return {
        ...state,
        items: state.items.map(item =>
          item.cartItemId === action.payload.cartItemId
            ? { ...item, quantity: action.payload.quantity }
            : item
        ).filter(item => item.quantity > 0)
      };

    case 'CLEAR_CART':
      return {
        ...state,
        items: []
      };

    default:
      return state;
  }
};

export const CartProvider = ({ children }) => {
  const [state, dispatch] = useReducer(cartReducer, { items: [] });

  const addItem = (item) => {
    const existingItem = state.items.find(cartItem => isSameItem(cartItem, item));
    const currentQuantity = existingItem ? existingItem.quantity : 0;

    // Check if we can add more items based on availability
    if (currentQuantity >= item.availability) {
      toast.error(`No hay más ${item.title} disponibles`, {
        description: `Solo quedan ${item.availability} en stock`,
        duration: 3000,
      });
      return;
    }

    dispatch({ type: 'ADD_ITEM', payload: item });

    // Show toast notification
    if (existingItem) {
      const newQuantity = existingItem.quantity + 1;
      const remaining = item.availability - newQuantity;
      toast.success(`Se agregó otro ${item.title} al carrito`, {
        description: `Cantidad: ${newQuantity}${remaining > 0 ? ` (quedan ${remaining})` : ' (último disponible)'}`,
        duration: 3000,
      });
    } else {
      const remaining = item.availability - 1;
      toast.success(`${item.title} agregado al carrito`, {
        description: `$${item.price}${remaining > 0 ? ` (quedan ${remaining})` : ' (último disponible)'}`,
        duration: 3000,
      });
    }
  };

  const removeItem = (cartItemId) => {
    dispatch({ type: 'REMOVE_ITEM', payload: cartItemId });
  };

  const updateQuantity = (cartItemId, quantity) => {
    dispatch({ type: 'UPDATE_QUANTITY', payload: { cartItemId, quantity } });
  };

  const clearCart = () => {
    dispatch({ type: 'CLEAR_CART' });
  };

  const getTotalItems = () => {
    return state.items.reduce((total, item) => total + item.quantity, 0);
  };

  const getTotalPrice = () => {
    return state.items.reduce((total, item) => total + (item.price * item.quantity), 0);
  };

  return (
    <CartContext.Provider value={{
      items: state.items,
      addItem,
      removeItem,
      updateQuantity,
      clearCart,
      getTotalItems,
      getTotalPrice
    }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error('useCart must be used within a CartProvider');
  }
  return context;
};
